/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {},

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    StartMove: function () {
        this._super();
    },

    ShowById(id, data) {
        this._super(id, data);
    },

    playCollectAnimation() {
        let isPlay = false
        let id = this._id
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
            this._showNode.active = true
            this._showNode.zIndex = 400 - this._symbolIdx + this._reelIdx * 10;
            isPlay = true
            let nodeSp = this._showNode.getChildByName("spine").getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, "collect", false)
            }
        }
        return isPlay
    },

    playBonusGameAnimation() {
        let isPlay = false
        let id = this._id
        if(this._showNode){
            this._showNode.active = false
        }
        let cfg = cc.vv.gameData.getGameCfg()
        if (cfg.symbol[id] && cfg.symbol[id].win_node) {
            this._showNode = cc.find(cfg.symbol[id].win_node, this.node)
            this._showNode.active = true
            this._showNode.zIndex = 400 - this._symbolIdx + this._reelIdx * 10;
            isPlay = true
            let nodeSp = this._showNode.getChildByName("spine").getComponent(sp.Skeleton)
            if (nodeSp) {
                nodeSp.setAnimation(0, "collect", false)
            }
        }
        return isPlay
    },
});