/**
 * @description
 */

cc.Class({
    extends: cc.Component,
    properties: {
        prizePool: cc.Node,
        pig: cc.Node,
        coins: [cc.Node],
        pigs: [cc.Node],
        coin_end: cc.Node,
        count_node: cc.Node,
        count_title: cc.Node,
        count_times: cc.Node,
        count_spine: sp.Skeleton,

        _endCallback: null,
        _coinPositions: [],
        _pigPositions: [],
        _bonusGame: null,
        _canSelect: false,
        _haveOpenReward: [],
    },

    onLoad() {
        for (let i = 0; i < this.coins.length; i++) {
            this._coinPositions.push(this.coins[i].position);
        }

        for (let i = 0; i < this.pigs.length; i++) {
            this._pigPositions.push(this.pigs[i].position);
        }

        for (let i = 0; i < this.pigs.length; i++) {
            let pig_node = this.pigs[i];
            pig_node.off(cc.Node.EventType.TOUCH_END);
            pig_node.on(cc.Node.EventType.TOUCH_END, async ()=>{
                if (!this._canSelect) {
                    return;
                }

                if (this._haveOpenReward.indexOf(i + 1) !== -1) {
                    return;
                }
                Global.SlotsSoundMgr.playEffect("pickGpig");
                this._canSelect = false;
                let req = {rtype:1, choiceId: (i + 1)};
                let result = await cc.vv.gameData.reqSubGame(req);
                if (result.code === 200) {
                    let bonusGame = result.data.bonusGame;
                    this._bonusGame = bonusGame;
                    let choiceId = result.data.choiceId;
                    this._haveOpenReward.push(choiceId);

                    this.count_times.getComponent("ImgSwitchCmp").setIndex(bonusGame.restCnt);
                    this.count_title.getComponent("ImgSwitchCmp").setIndex(bonusGame.restCnt >= 2 ? 1 : 0);

                    let select_pig = this.pigs[choiceId - 1];
                    let spine = cc.find("spine", select_pig).getComponent(sp.Skeleton);
                    spine.setAnimation(0, "Pig_boom", false);

                    await cc.vv.gameData.awaitTime(0.5);

                    let item = bonusGame.items[choiceId - 1];
                    if (item.jackpot) {
                        let jackpot = cc.find("jackpot", select_pig);
                        jackpot.active = true;
                        jackpot.scale = 0;
                        jackpot.getComponent("ImgSwitchCmp").setIndex(item.jackpot.id - 1);
                        cc.tween(jackpot)
                            .to(0.5, {scale: 1})
                            .start();

                        await cc.vv.gameData.awaitTime(1);

                        await cc.vv.gameData.GetSlotsScript().popJackpotDialog(item.jackpot);
                    } else {
                        let coin = cc.find("coin", select_pig);
                        coin.active = true;
                        coin.scale = 0;
                        coin.getComponent(cc.Label).string = Global.formatNumShort(item.coin, 0);
                        cc.tween(coin)
                            .to(0.5, {scale: 1})
                            .start();
                    }

                    if (bonusGame.isEnd) {
                        Global.SlotsSoundMgr.playEffect("koiSure");
                        this.endGame(bonusGame);
                    } else {
                        await cc.vv.gameData.awaitTime(1);

                        this._canSelect = true;
                    }
                }
            });
        }
    },

    reconnectPickGame(bonusGame) {
        return new Promise(async (success)=>{
            this.node.active = true;
            this._endCallback = success;
            this.reset();
            this._bonusGame = bonusGame;

            cc.find("LMSlots_PrizePool_1", this.node.parent).active = false;
            this.prizePool.active = true;
            this.prizePool.getComponent("LMSlots_PrizePool_Base").PausePool([
                {prizeType: 0, pauseNum: bonusGame.jackpotValues[0]},
                {prizeType: 1, pauseNum: bonusGame.jackpotValues[1]},
                {prizeType: 2, pauseNum: bonusGame.jackpotValues[2]},
                {prizeType: 3, pauseNum: bonusGame.jackpotValues[3]},
                {prizeType: 4, pauseNum: bonusGame.jackpotValues[4]}
            ]);

            this.pig.active = false;
            this.count_node.active = true;

            for (let i = 0; i < this.pigs.length; i++) {
                let pig_node = this.pigs[i];
                let info = bonusGame.items[i];
                pig_node.active = true;
                if (!info.isOpen) {
                    pig_node.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, "Pig_loop", true);
                } else {
                    let spine = cc.find("spine", pig_node).getComponent(sp.Skeleton);
                    spine.setAnimation(0, "Pig_boom", false);

                    if (info.jackpot) {
                        let jackpot = cc.find("jackpot", pig_node);
                        jackpot.active = true;
                        jackpot.getComponent("ImgSwitchCmp").setIndex(info.jackpot.id - 1);
                    } else {
                        let coin = cc.find("coin", pig_node);
                        coin.active = true;
                        coin.getComponent(cc.Label).string = Global.formatNumShort(info.coin, 0);
                    }
                }
            }

            this.count_times.getComponent("ImgSwitchCmp").setIndex(bonusGame.restCnt);

            this._canSelect = true;
        });
    },

    startPickGame(bonusGame) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm("bgbgm");
            this.node.active = true;
            this._endCallback = success;
            this.reset();
            this._bonusGame = bonusGame;

            cc.find("LMSlots_PrizePool_1", this.node.parent).active = false;
            this.prizePool.active = true;
            this.prizePool.getComponent("LMSlots_PrizePool_Base").PausePool([
                {prizeType: 0, pauseNum: bonusGame.jackpotValues[0]},
                {prizeType: 1, pauseNum: bonusGame.jackpotValues[1]},
                {prizeType: 2, pauseNum: bonusGame.jackpotValues[2]},
                {prizeType: 3, pauseNum: bonusGame.jackpotValues[3]},
                {prizeType: 4, pauseNum: bonusGame.jackpotValues[4]}
            ]);

            this.pig.scale = 0;
            let spine = this.pig.getComponent(sp.Skeleton);
            cc.tween(this.pig)
                .to(0.5, {scale: 1})
                .call(()=>{
                    spine.setAnimation(0, "Tpig_luoxia_tiao", false);
                    Global.SlotsSoundMgr.playEffect("GpigJump");
                    spine.setCompleteListener(async ()=>{
                        spine.setCompleteListener(null);
                        Global.SlotsSoundMgr.playEffect("GpigJumpOne");
                        spine.setAnimation(0, "Tpig_luoxia_tiao2", false);
                        spine.addAnimation(0, "Tpig_loop", true);

                        Global.SlotsSoundMgr.playEffect("5coinUp");
                        cc.tween(this.node)
                            .delay(2.5)
                            .call(()=>{
                                Global.SlotsSoundMgr.playEffect("5coinMerge");
                            })
                            .start();
                        for (let i = 0; i < this.coins.length; i++) {
                            let coin_node = this.coins[i];
                            let item = bonusGame.items[i];
                            coin_node.active = true;
                            coin_node.position = this.pig.position;
                            let coin = cc.find("coin", coin_node);
                            let jackpot = cc.find("jackpot", coin_node);
                            let bg = cc.find("blackCoin", coin_node);
                            coin.active = !item.jackpot;
                            jackpot.active = item.jackpot;
                            bg.getComponent("ImgSwitchCmp").setIndex(item.jackpot ? 1 : 0);
                            if (item.jackpot) {
                                jackpot.getComponent("ImgSwitchCmp").setIndex(item.jackpot.id - 1);
                            } else {
                                coin.getComponent(cc.Label).string = Global.formatNumShort(item.coin, 0);
                            }
                            cc.tween(coin_node)
                                .to(0.5, {position: this._coinPositions[i]}, {easing: "backOut"})
                                .delay(2)
                                .to(0.5, {position: this.coin_end.position})
                                .call(()=>{
                                    coin_node.active = false;
                                })
                                .start();
                        }
                    })
                })
                .start();

            await cc.vv.gameData.awaitTime(6);

            spine.setAnimation(0, "JinBiZaZhu", false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                this.pig.active = false;
            });

            await cc.vv.gameData.awaitTime(2);

            Global.SlotsSoundMgr.playEffect("5pigUp");
            for (let i = 0; i < this.pigs.length; i++) {
                let pig_node = this.pigs[i];
                pig_node.active = true;
                pig_node.position = this.pig.position;
                pig_node.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, "Pig_loop", true);
                cc.tween(pig_node)
                    .to(0.5, {position: this._pigPositions[i]})
                    .start();
            }

            this.count_node.active = true;
            this.count_node.scale = 0;
            cc.tween(this.count_node)
                .to(0.5, {scale: 1})
                .start();
            this.count_times.getComponent("ImgSwitchCmp").setIndex(0);

            await cc.vv.gameData.awaitTime(0.5);
            for (let i = 0; i < bonusGame.restCnt; i++) {
                cc.tween(this.count_times)
                    .to(0.2, {scale: 0})
                    .call(()=>{
                        Global.SlotsSoundMgr.playEffect("pickLeft");
                        this.count_times.getComponent("ImgSwitchCmp").setIndex(i + 1);
                        this.count_title.getComponent("ImgSwitchCmp").setIndex(i + 1 >= 2 ? 1 : 0);
                        this.count_spine.node.active = true;
                        this.count_spine.setAnimation(0, "BG_PicksLeft", false);
                        this.count_spine.setCompleteListener(()=>{
                            this.count_spine.setCompleteListener(null);
                            this.count_spine.node.active = false;
                        })
                    })
                    .to(0.2, {scale: 1}, {easing: "backOut"})
                    .start();

                await cc.vv.gameData.awaitTime(0.4);
            }

            this._canSelect = true;
        });
    },

    async endGame(bonusGame) {
        for (let i = 0; i < this.pigs.length; i++) {
            let pig_node = this.pigs[i];
            let item = bonusGame.items[i];
            if (this._haveOpenReward.indexOf(i + 1) === -1) {
                cc.find("spine", pig_node).active = false;
                cc.find("grey", pig_node).active = true;
                if (item.jackpot) {
                    let jackpot = cc.find("jackpot", pig_node);
                    jackpot.active = true;
                    jackpot.getComponent("ImgSwitchCmp").setIndex(item.jackpot.id - 1);
                    jackpot.color = cc.Color.GRAY;
                } else {
                    let coin = cc.find("coin", pig_node);
                    coin.active = true;
                    coin.getComponent(cc.Label).string = Global.formatNumShort(item.coin, 0);
                    coin.color = cc.Color.GRAY;
                }
            }
        }

        await cc.vv.gameData.awaitTime(1);

        this.node.active = false;
        cc.find("LMSlots_PrizePool_1", this.node.parent).active = true;
        if (this._endCallback) {
            this._endCallback();
            this._endCallback = null;
        }
    },

    getBonusGame() {
        return this._bonusGame;
    },

    reset() {
        this.pig.active = true;

        for (let coin of this.coins) {
            coin.active = false;
        }

        for (let pig of this.pigs) {
            pig.active = false;
            cc.find("spine", pig).active = true;
            cc.find("grey", pig).active = false;
            cc.find("jackpot", pig).active = false;
            cc.find("jackpot", pig).color = cc.Color.WHITE;
            cc.find("coin", pig).active = false;
            cc.find("coin", pig).color = cc.Color.WHITE;
        }

        this.count_node.active = false;

        this._canSelect = false;
        this._haveOpenReward = [];
    },
});