/**
 * @description
 */

cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {

    },

    //旋转
    StartMove:function(){
        this._super();
    },

    //列停止
    OnReelSpinEnd:function(){
        this._super();
    },

    playReelStop(){
        this._super();

        if (this._originResult) {
            for(let i = 0; i < this._originResult.length; i++){
                let item = this._symbols[i]
                if (item.GetShowId() === this._cfg.bonusId ||
                    item.GetShowId() === this._cfg.bonusGameId) {
                    Global.SlotsSoundMgr.playEffect("reelpig");
                }
            }
        }
    },

    ShowAntiEffect:function(bShow,name){
        if (bShow == false) {
            if (this._cfg.reelStateInfo) {
                for (let info of this._cfg.reelStateInfo) {
                    let node = cc.find(info.antiNode,this.node)
                    if(node && node.active){
                        node.active = false
                        // 既然不是循环的播放，就不需要主动停止
                        // 点立即停止的时候需要停止加速音效
                        if(this._stopRightNow){
                            cc.vv.AudioManager.stopEffectByName(info.antSound);
                        }

                    }
                }
            }
        }else{
            let node = cc.find( name,this.node)
            if(node){
                node.active = bShow
            }
            else{
                cc.log("未找到加速节点：mask/node_anti");
            }
        }
    },
});